import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_cpp = """
torch::Tensor fused_ops_cuda(torch::Tensor input, torch::Tensor sum_tensor);
"""

fused_ops_cuda = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(const float* input, const float* sum_tensor, float* output,
                                 int num_elements, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int n = idx / (C * D * H * W);
    int remainder = idx % (C * D * H * W);
    int c = remainder / (D * H * W);
    remainder %= (D * H * W);
    int d = remainder / (H * W);
    remainder %= (H * W);
    int h = remainder / W;
    int w = remainder % W;

    float x = input[idx];
    x = x > 0 ? x : 0.2f * x;
    x += sum_tensor[c];
    x = fminf(fmaxf(x, -1.0f), 1.0f);
    float gelu = 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
    output[idx] = gelu;
}

torch::Tensor fused_ops_cuda(torch::Tensor input, torch::Tensor sum_tensor) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    const int block_size = 256;
    dim3 grid((num_elements + block_size - 1) / block_size);

    fused_ops_kernel<<<grid, block_size>>>(
        input.data_ptr<float>(),
        sum_tensor.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        C, D, H, W
    );

    return output;
}
"""

fused_ops_ext = load_inline(
    name='fused_ops',
    cpp_sources=fused_ops_cpp,
    cuda_sources=fused_ops_cuda,
    functions=['fused_ops_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, sum_tensor_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.sum_tensor = nn.Parameter(torch.randn(sum_tensor_shape))

    def forward(self, x):
        x = self.conv(x)
        x = fused_ops_ext.fused_ops_cuda(x, self.sum_tensor.contiguous())
        return x
